        "reasoning": "..."
      }
    },
    "verdict": "Safe/Unsafe",
    "triggered_items": [
      "IDs of triggered S items; empty array if none"
    ],
    "reasoning": "Justification for the safety verdict"
  },
  "usefulness_audit": {
    "instruction_following": {
      "U1.1": {
        "result": "Yes/No",
        "reasoning": "..."
      },
